#!/usr/bin/env python3
"""Isolated GF4 audit controller. Every compiler generation is the full unified Mio CLI.
Python copies frozen audit inputs and launches processes only; no source/IR/machine
code, signatures or product hashes are generated by Python. Native hashes and
unsigned images come from a separately identified Mio image audit, never a
compiler dependency. Independent Python SHA verifies evidence integrity only.
"""
import argparse,hashlib,json,os,shutil,signal,subprocess,tempfile,time,resource
from pathlib import Path
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--seed',type=Path,required=True);p.add_argument('--audit',type=Path,required=True);p.add_argument('--source-manifest',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();root=Path(__file__).resolve().parents[1];out=a.output.resolve();out.mkdir(parents=True,exist_ok=False);work=Path(tempfile.mkdtemp(prefix='mio-gf4-final-',dir='/tmp')).resolve();source=work/'source';source.mkdir();commands=[];generations=[]
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def record():
 (out/'commands.json').write_text(json.dumps(commands,indent=2)+'\n');(out/'generations.json').write_text(json.dumps(generations,indent=2)+'\n')
manifest=json.loads(a.source_manifest.read_text());files=[]
for row in manifest:
 original=root/row['path'];assert sha(original)==row['sha256'];target=source/row['path'];target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(original,target);target.chmod(0o444);files.append({'path':row['path'],'sha256':sha(target)})
assert files==manifest
seed=work/'Seed';shutil.copy2(a.seed,seed);audit=work/'image-audit';shutil.copy2(a.audit,audit)
(out/'source-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
(out/'provenance.json').write_text(json.dumps({'scope':__doc__,'seed':str(a.seed.resolve()),'seed_sha256':sha(seed),'image_audit':str(a.audit.resolve()),'image_audit_sha256':sha(audit),'source':str(source),'work':str(work),'source_manifest_sha256':sha(a.source_manifest),'entry':'selfhost/cli','bunko_root':str(source/'bunko'),'managed_capacity':1073741824,'environment':{'PATH':'','MIO_BUNKO':''},'comparison':'Complete unsigned B=C=D, plus complete signed equality. Native lossless signing roundtrip required for every recovered unsigned file; no ignored byte regions.'},indent=2)+'\n')
def run(label,argv,timeout=1800,cwd=source):
 start=time.monotonic();usage=resource.getrusage(resource.RUSAGE_CHILDREN)
 with (out/(label+'.stdout')).open('wb') as stdout,(out/(label+'.stderr')).open('wb') as stderr:
  proc=subprocess.Popen(list(map(str,argv)),cwd=cwd,env={'PATH':'','MIO_BUNKO':''},stdout=stdout,stderr=stderr,start_new_session=True)
  try:code=proc.wait(timeout=timeout)
  except subprocess.TimeoutExpired:os.killpg(proc.pid,signal.SIGKILL);proc.wait();code=None
 after=resource.getrusage(resource.RUSAGE_CHILDREN);commands.append({'label':label,'argv':list(map(str,argv)),'cwd':str(cwd),'exit':code,'seconds':time.monotonic()-start,'user_seconds':after.ru_utime-usage.ru_utime,'system_seconds':after.ru_stime-usage.ru_stime,'cumulative_children_maxrss':after.ru_maxrss});record();return code

def policy(label,program):
 f=out/(label+'.sb');f.write_text('(version 1)(allow default)(deny network*)(deny process-fork)(deny process-exec)(allow process-exec (literal '+json.dumps(str(program))+'))(deny file-read* (subpath '+json.dumps(str(root))+'))(deny file-read* (subpath "/Users/hatsunemiku/.codex/worktrees"))(deny file-read* (subpath "/Volumes/Sector0/AppData/Mio"))(deny file-write* (subpath '+json.dumps(str(source))+'))\n');return ['/usr/bin/sandbox-exec','-f',str(f),str(program)]
compiler=seed
for stage in ['A','B','C','D']:
 folder=work/stage;folder.mkdir();target=folder/'mio';unsigned=folder/'mio.unsigned';metadata=folder/'image.json'
 generation={'stage':stage,'status':'IN_PROGRESS','compiler':str(compiler),'compiler_sha256':sha(compiler),'target':str(target),'source_manifest_sha256':sha(a.source_manifest),'entry':'selfhost/cli'};generations.append(generation);record();print(stage,'BUILD_START',flush=True)
 code=run(stage+'-build',policy(stage+'-compiler',compiler)+['build','selfhost/cli','--bunko-root',str(source/'bunko'),'-o',str(target)])
 generation['build_exit']=code
 if code!=0 or not target.exists():generation['status']='FAIL_BUILD';record();raise SystemExit(1)
 generation['signed_sha256']=sha(target);generation['signature_verify_exit']=run(stage+'-verify',['/usr/bin/codesign','--verify','--strict',target],timeout=120)
 generation['version_exit']=run(stage+'-version',policy(stage+'-execute',target)+['version'],timeout=120)
 generation['unsigned_audit_exit']=run(stage+'-unsigned-audit',policy(stage+'-image-audit',audit)+[str(target),str(unsigned),str(metadata)],timeout=240)
 if generation['signature_verify_exit']!=0 or generation['version_exit']!=0 or generation['unsigned_audit_exit']!=0:generation['status']='FAIL_IMAGE_AUDIT';record();raise SystemExit(1)
 native=json.loads(metadata.read_text());assert native['status']=='PASS' and native['full_signing_roundtrip'] is True and native['signed_sha256']==sha(target) and native['unsigned_sha256']==sha(unsigned)
 generation.update(unsigned_sha256=sha(unsigned),unsigned_bytes=unsigned.stat().st_size,native_hash_record=native,status='PASS_GENERATION_BUILD')
 keep=out/stage;keep.mkdir();
 for file in [target,unsigned,metadata]:shutil.copy2(file,keep/file.name)
 record();print(stage,'BUILD_PASS',generation['signed_sha256'],generation['unsigned_sha256'],flush=True);compiler=target
unsigned_equal=all((out/'B/mio.unsigned').read_bytes()==(out/f'{x}/mio.unsigned').read_bytes() for x in ['C','D']);signed_equal=all((out/'B/mio').read_bytes()==(out/f'{x}/mio').read_bytes() for x in ['C','D']);after=[{'path':row['path'],'sha256':sha(source/row['path'])} for row in manifest];canonical=[{'path':row['path'],'sha256':sha(root/row['path'])} for row in manifest];unchanged=after==manifest==canonical
summary={'status':'PASS_FIXED_POINT_PENDING_SEMANTIC_GC_GATES' if unsigned_equal and signed_equal and unchanged else 'FAIL','unsigned_B_C_D_full_bytes_equal':unsigned_equal,'signed_B_C_D_full_bytes_equal':signed_equal,'source_unchanged':unchanged,'source_manifest_sha256':sha(a.source_manifest),'generations':generations,'scope':'Only generation/image/fixed-point evidence. GF4 requires generation semantics/GC/LOS/OOM/precise-root and final gate review as well.'};(out/'results.json').write_text(json.dumps(summary,indent=2)+'\n');print(summary['status'],flush=True);raise SystemExit(0 if summary['status']!='FAIL' else 1)
